510	// SetDropScope installs the custom scope's rules (nil for none) and whether the drop gate uses them
511	// (Burp's "Use custom scope") or the suite scope. The scope passed is owned by this one afterwards.
512	func (s *Scope) SetDropScope(custom *Scope, use bool) {
513		// Read the candidate's rules before the write lock: it is not installed yet, so no other
514		// goroutine can mutate it mid-compare, and the comparison then never takes a child lock
515		// inside the parent's.
516		var newRules []*ScopeRule
517		if custom != nil {
518			newRules = custom.Rules()
519		}
520		s.mu.Lock()
521		if scopeRulesSemanticallyEqual(s.dropScopeRulesLocked(), newRules) && s.dropCustom == (use && custom != nil) {
522			// Reinstalling the identical custom scope in the identical mode changes no answer.
523			s.mu.Unlock()
524			return
525		}
526		s.dropScope = custom
527		s.dropCustom = use && custom != nil
528		before, allowAll := s.changeSnapshot()
529		s.mu.Unlock()
530		s.notifyUnconditional(ScopeChange{Before: before, After: before, AllowAllBefore: allowAll,
531			AllowAllAfter: allowAll, Operation: "drop_scope"})
532	}
