534	// dropScopeRulesLocked returns the installed custom drop scope's rules, nil when none is
535	// installed. Callers hold the write lock; the custom scope is owned by this one, so its own
536	// read lock is a leaf.
537	func (s *Scope) dropScopeRulesLocked() []*ScopeRule {
538		if s.dropScope == nil {
539			return nil
540		}
541		return s.dropScope.Rules()
542	}
543	
544	// scopeRulesSemanticallyEqual compares two rule lists by meaning: kind, pattern, enabled flag
545	// and the three optional limiters, in order. Compiled arms and parse faults are derived state,
546	// never the identity.
547	func scopeRulesSemanticallyEqual(a, b []*ScopeRule) bool {
548		if len(a) != len(b) {
549			return false
550		}
551		for i := range a {
552			x, y := a[i], b[i]
553			if x.Kind != y.Kind || x.Pattern != y.Pattern || x.Enabled != y.Enabled ||
554				!stringPtrEqual(x.PathPrefix, y.PathPrefix) ||
555				!uint16PtrEqual(x.Port, y.Port) ||
556				!stringPtrEqual(x.Protocol, y.Protocol) {
557				return false
558			}
559		}
560		return true
561	}
562	
563	func stringPtrEqual(a, b *string) bool {
564		if (a == nil) != (b == nil) {
565			return false
566		}
567		return a == nil || *a == *b
568	}
569	
570	func uint16PtrEqual(a, b *uint16) bool {
571		if (a == nil) != (b == nil) {
572			return false
573		}
574		return a == nil || *a == *b
575	}
