604	func (s *Server) updateScope(w http.ResponseWriter, r *http.Request) {
605		var req ScopeRequest
606		if err := requestJSON(w, r, nil).Decode(&req); err != nil {
607			http.Error(w, "Invalid request body", http.StatusBadRequest)
608			return
609		}
610	
611		// The library actions answer for themselves — a count, and whether a save replaced something —
612		// so they return before the shared "status: ok" tail below, and before persistScope: a save or a
613		// delete does not touch the live rule list, and a load persists it itself.
614		switch req.Action {
615		case "library_save", "library_load", "library_delete":
616			s.updateScopeLibrary(w, req)
617			return
618		}
619	
620		switch req.Action {
621		case "drop_out_of_scope":
622			// One round trip for the switch, like "toggle" for a rule row. When on, every scope
623			// refusal becomes an egress refusal — the proxy stops issuing requests to hosts the
624			// scope excludes — which is the safety control 5j4i asks for. The switch itself is
625			// not persisted here; persistence rides the same save the scope rows ride (see
626			// persistScope), so the durable document is never a half-state.
627			if req.Enabled == nil {
628				http.Error(w, "Enabled is required for drop_out_of_scope", http.StatusBadRequest)
629				return
630			}
631			s.scope.SetDropOutOfScope(*req.Enabled)
632			if s.persist != nil {
633				s.persist.SaveScopeDropOutOfScope(*req.Enabled)
634			}
635		case "drop_scope":
